import pandas as pd

df = pd.DataFrame({
    "ticker": ["AAPL", "MSFT", "JPM", "XOM"],
    "sector": ["tech", "tech", "fin", "energy"],
    "ret":    [0.012, -0.003, 0.008, 0.015],
})
print(df.groupby("sector")["ret"].mean().round(4).to_dict())
